import {useEffect} from 'react';import {io,Socket} from 'socket.io-client';let socket:Socket|null=null;export function useSocket(events:Record<string,(data:any)=>void>={}){useEffect(()=>{socket??=io(import.meta.env.VITE_SOCKET_URL||location.origin,{withCredentials:true,reconnection:true,reconnectionDelayMax:5000});Object.entries(events).forEach(([e,h])=>socket!.on(e,h));const timer=setInterval(()=>socket?.emit('heartbeat',()=>{}),25000);return()=>{Object.entries(events).forEach(([e,h])=>socket!.off(e,h));clearInterval(timer)}},[...Object.values(events)]);return socket}
